select jsonb_build_object('workspace',(select jsonb_build_object('id',id,'name',legal_name,'country',country,'currency',base_currency)from public.workspaces where id='d621017c-e9bd-4334-a07f-5e7b6d31ef6e'),'accounts',(select count(*)from public.accounts where workspace_id='d621017c-e9bd-4334-a07f-5e7b6d31ef6e'),'vat_candidates',(select count(*)from public.vat_codes where workspace_id='d621017c-e9bd-4334-a07f-5e7b6d31ef6e'),'fixed_asset_table',to_regclass('public.fixed_assets')is not null,'freefinance_staging_tables',(select count(*)from information_schema.tables where table_schema='public'and table_name in('freefinance_import_batches','freefinance_journal_staging','freefinance_invoice_staging','freefinance_asset_staging')),'quickbooks_staging_tables',(select count(*)from information_schema.tables where table_schema='public'and table_name in('quickbooks_reconciliation_batches','quickbooks_reconciliation_rows')),'imported_transactions',(select count(*)from public.transactions where workspace_id='d621017c-e9bd-4334-a07f-5e7b6d31ef6e'))verification;
